<template>
  <div class="box"><div class="header-actions"><Icon class="icon" icon="material-symbols-light:arrow-back-ios-new" width="20" height="20" @click="handleBack"/><Icon v-perm="'email:delete'" class="icon" icon="uiw:delete" width="16" height="16" @click="handleDelete"/><span class="star" v-if="emailStore.contentData.showStar"><Icon class="icon" @click="changeStar" v-if="email.isStar" icon="fluent-color:star-16" width="20" height="20"/><Icon class="icon" @click="changeStar" v-else icon="solar:star-line-duotone" width="18" height="18"/></span><Icon class="icon" v-if="emailStore.contentData.showReply" v-perm="'email:send'" @click="openReply" icon="la:reply" width="21" height="21"/><el-dropdown v-if="emailStore.contentData.showReply" @command="handleReplyCommand"><Icon class="icon" icon="iconoir:arrow-up-right" width="20" height="20"/><template #dropdown><el-dropdown-menu><el-dropdown-item command="replyAll">Reply all</el-dropdown-item><el-dropdown-item command="forward">Forward</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div><el-scrollbar class="scrollbar"><div class="container"><div class="email-title">{{email.subject}}</div><div class="content"><div class="email-info"><div><div class="send"><span class="send-source">{{$t('from')}}</span><div class="send-name"><span class="send-name-title">{{email.name}}</span><span><{{email.sendEmail}}></span></div></div><div class="receive"><span class="source">{{$t('recipient')}}</span><span class="receive-email">{{formateReceive(email.recipient)}}</span></div><div class="date"><div>{{formatDetailDate(email.createTime)}}</div></div></div></div><el-scrollbar class="htm-scrollbar" :class="email.attList.length===0?'bottom-distance':''"><ShadowHtml class="shadow-html" :html="formatImage(email.content)" v-if="email.content"/><pre v-else class="email-text">{{email.text}}</pre></el-scrollbar><div class="att" v-if="email.attList.length>0"><div class="att-title"><span>{{$t('attachments')}}</span><span>{{$t('attCount',{total:email.attList.length})}}</span></div><div class="att-box"><div class="att-item" v-for="att in email.attList" :key="att.attId"><div class="att-name">{{att.filename}}</div><div class="att-size">{{formatBytes(att.size)}}</div><a :href="cvtR2Url(att.key)" download><Icon icon="system-uicons:push-down" width="22" height="22"/></a></div></div></div></div></div></el-scrollbar></div>
</template>
<script setup>
import ShadowHtml from '@/components/shadow-html/index.vue';import {reactive,ref,watch,onMounted,onUnmounted} from 'vue';import {useRouter} from 'vue-router';import {ElMessageBox} from 'element-plus';import {emailDelete,emailRead} from '@/request/email.js';import {Icon} from '@iconify/vue';import {useEmailStore} from '@/store/email.js';import {useAccountStore} from '@/store/account.js';import {formatDetailDate} from '@/utils/day.js';import {starAdd,starCancel} from '@/request/star.js';import {getExtName,formatBytes} from '@/utils/file-utils.js';import {cvtR2Url,toOssDomain} from '@/utils/convert.js';import {useSettingStore} from '@/store/setting.js';import {allEmailDelete} from '@/request/all-email.js';import {useUiStore} from '@/store/ui.js';import {useI18n} from 'vue-i18n';import {EmailUnreadEnum} from '@/enums/email-enum.js';
const uiStore=useUiStore(),settingStore=useSettingStore(),accountStore=useAccountStore(),emailStore=useEmailStore(),router=useRouter(),email=emailStore.contentData.email,showPreview=ref(false),srcList=reactive([]),{t}=useI18n();watch(()=>accountStore.currentAccountId,()=>handleBack());onMounted(()=>{if(emailStore.contentData.showUnread&&email.unread===EmailUnreadEnum.UNREAD){email.unread=EmailUnreadEnum.READ;emailRead([email.emailId])}window.addEventListener('keydown',handleKeyDown)});onUnmounted(()=>window.removeEventListener('keydown',handleKeyDown));
function handleKeyDown(e){if(e.key==='Escape'&&!document.querySelector('.el-message-box')&&!document.querySelector('.write-box'))handleBack()}function openReply(){uiStore.writerRef.openReply(email)}function handleReplyCommand(command){if(command==='replyAll')uiStore.writerRef.openReplyAll(email);if(command==='forward')uiStore.writerRef.openForward(email)}function toMessage(m){return m?JSON.parse(m).message:''}function formatImage(c){return String(c||'').replace(/{{domain}}/g,toOssDomain(settingStore.settings.r2Domain)+'/')}function formateReceive(r){try{return JSON.parse(r).map(i=>i.address).join(', ')}catch{return r||''}}function changeStar(){if(email.isStar){email.isStar=0;starCancel(email.emailId)}else{email.isStar=1;starAdd(email.emailId)}}function handleBack(){router.back()}function handleDelete(){ElMessageBox.confirm(t('delEmailConfirm'),{confirmButtonText:t('confirm'),cancelButtonText:t('cancel'),type:'warning'}).then(()=>{if(emailStore.contentData.delType==='logic')emailDelete(email.emailId);else allEmailDelete(email.emailId);router.back()})}function isImage(f){return ['png','jpg','jpeg','bmp','gif','jfif'].includes(getExtName(f))}
</script>
<style scoped lang="scss">.box{height:100%;overflow:hidden}.header-actions{padding:9px 15px 8px;display:flex;align-items:center;gap:20px;box-shadow:var(--header-actions-border)}.icon{cursor:pointer}.scrollbar{height:calc(100% - 38px);width:100%}.container{font-size:14px;padding:20px}.email-title{font-size:18px;font-weight:600;margin-bottom:16px}.content{height:calc(100% - 40px)}.email-info{margin-bottom:12px}.send,.receive{display:flex;margin:6px 0}.send-source,.source{width:70px;color:var(--el-text-color-secondary)}.send-name{display:flex;gap:8px}.htm-scrollbar{max-height:calc(100vh - 260px)}.att{margin-top:15px}.att-item{display:flex;align-items:center;gap:12px;padding:8px 0}</style>
